public int twoCharacters(String s) {
    int n = s.length();
    int best = 0;
    for (int mask = 1; mask < (1 << n); mask++) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) != 0) sb.append(s.charAt(i));
        }
        String t = sb.toString();
        if (isValid(t)) best = Math.max(best, t.length());
    }
    return best;
}

private boolean isValid(String t) {
    java.util.Set<Character> distinct = new java.util.HashSet<>();
    for (int i = 0; i < t.length(); i++) {
        distinct.add(t.charAt(i));
        if (i > 0 && t.charAt(i) == t.charAt(i - 1)) return false;
    }
    return distinct.size() == 2;
}

