def two_characters(self, s: str) -> int:
    from itertools import combinations
    n = len(s)
    best = 0
    for r in range(2, n + 1):
        for idxs in combinations(range(n), r):
            t = ''.join(s[i] for i in idxs)
            if len(set(t)) == 2 and all(t[i] != t[i + 1] for i in range(len(t) - 1)):
                best = max(best, len(t))
    return best

