public int twoCharacters(String s) {
    java.util.List<Character> distinct = new java.util.ArrayList<>(
        new java.util.TreeSet<>(s.chars().mapToObj(c -> (char) c).toList()));
    int best = 0;
    for (int i = 0; i < distinct.size(); i++) {
        for (int j = i + 1; j < distinct.size(); j++) {
            char x = distinct.get(i), y = distinct.get(j);
            StringBuilder t = new StringBuilder();
            boolean ok = true;
            for (int k = 0; k < s.length(); k++) {
                char c = s.charAt(k);
                if (c != x && c != y) continue;
                if (t.length() > 0 && t.charAt(t.length() - 1) == c) { ok = false; break; }
                t.append(c);
            }
            if (ok && t.length() > 1) best = Math.max(best, t.length());
        }
    }
    return best;
}

