def two_characters(self, s: str) -> int:
    distinct = sorted(set(s))
    best = 0
    for i in range(len(distinct)):
        for j in range(i + 1, len(distinct)):
            x, y = distinct[i], distinct[j]
            t = [c for c in s if c == x or c == y]
            if all(t[k] != t[k + 1] for k in range(len(t) - 1)) and len(t) > 1:
                best = max(best, len(t))
    return best

